create table public.challenge_attempts (id uuid primary key default gen_random_uuid(), challenge_id uuid not null references public.challenges(id) on delete restrict, student_id uuid not null references public.profiles(id) on delete restrict, started_at timestamptz not null default now(), submitted_at timestamptz, response jsonb, evaluation jsonb, score numeric(6,2) check (score between 0 and 100), completed boolean not null default false, created_at timestamptz not null default now());;
